5	const LOYALTY_DISCOUNT_RATE = 0.2;
6	const LOYALTY_THRESHOLD_YEARS = 2;
7	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
8	
9	export interface Item {
10	  type: string;
11	  material?: string;
12	  enchantment?: number;
13	  cursed?: boolean;
14	}
15	
16	const BASE_PREMIUMS: Record<string, number> = {
17	  sword: 100,
18	  amulet: 60,
19	  staff: 80,
20	  potion: 40,
21	};
22	
23	const COMPONENT_BASE_PREMIUM = 25;
24	const COMPONENT_BLOCK_SIZE = 3;
25	const COMPONENT_BLOCK_PREMIUM = 60;
26	
27	const PROCESSING_FEE = 5;
28	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
29	
30	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
31	
32	const isMainItem = (item: Item): boolean => item.type in BASE_PREMIUMS;
33	
34	const validateItemType = (item: Item): void => {
35	  if (!isMainItem(item) && !COMPONENT_TYPES.has(item.type)) {
36	    throw new Error(`Unknown item type: ${item.type}`);
37	  }
38	};
39	
40	const componentsBasePremium = (components: Item[]): number => {
41	  const countsByType = new Map<string, number>();
42	  for (const component of components) {
43	    countsByType.set(component.type, (countsByType.get(component.type) ?? 0) + 1);
44	  }
45	  let total = 0;
46	  for (const count of countsByType.values()) {
47	    total +=
48	      count === COMPONENT_BLOCK_SIZE
49	        ? COMPONENT_BLOCK_PREMIUM
50	        : count * COMPONENT_BASE_PREMIUM;
51	  }
52	  return total;
53	};
54	
55	const CURSED_SURCHARGE_RATE = 0.5;
56	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
57	const HIGH_ENCHANTMENT_THRESHOLD = 5;
58	
59	const itemBasePremium = (item: Item): number =>
60	  BASE_PREMIUMS[item.type] ?? COMPONENT_BASE_PREMIUM;
61	
62	const itemModifiersSurcharge = (item: Item, base: number): number => {
63	  let surcharge = 0;
64	  if (item.cursed) surcharge += base * CURSED_SURCHARGE_RATE;
65	  if ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD) {
66	    surcharge += base * HIGH_ENCHANTMENT_SURCHARGE_RATE;
67	  }
68	  return surcharge;
69	};
70	
71	const calculateBasePremium = (items: Item[]): number => {
72	  const mainItems = items.filter(isMainItem);
73	  const components = items.filter((item) => !isMainItem(item));
74	  const mainItemsPremium = mainItems.reduce(
75	    (sum, item) => sum + itemBasePremium(item),
76	    0,
77	  );
78	  return mainItemsPremium + componentsBasePremium(components);
79	};
80	
81	const calculateItemModifiersSurcharge = (items: Item[]): number =>
82	  items.reduce(
83	    (sum, item) => sum + itemModifiersSurcharge(item, itemBasePremium(item)),
84	    0,
85	  );
86	
87	export const calculatePremium = (
88	  customer: Customer,
89	  items: Item[],
90	  isFirstContract: boolean,
91	): number => {
92	  items.forEach(validateItemType);
93	  const basePremium = calculateBasePremium(items);
94	  const itemModifiers = calculateItemModifiersSurcharge(items);
95	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
96	  const loyaltyDiscount =
97	    customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS
98	      ? basePremium * LOYALTY_DISCOUNT_RATE
99	      : 0;
100	  const followUpContractDiscount = isFirstContract
101	    ? 0
102	    : basePremium * FOLLOW_UP_CONTRACT_DISCOUNT_RATE;
103	  return Math.ceil(
104	    basePremium +
105	      itemModifiers +
106	      firstInsuranceSurcharge -
107	      loyaltyDiscount -
108	      followUpContractDiscount +
109	      PROCESSING_FEE,
110	  );
111	};
