3	const INSURANCE_VALUES: Record<string, number> = {
4	  sword: 1000,
5	  amulet: 600,
6	  staff: 800,
7	  potion: 400,
8	};
9	const COMPONENT_INSURANCE_VALUE = 250;
10	const CAP_MULTIPLIER = 2;
11	
12	const itemInsuranceValue = (item: Item): number =>
13	  INSURANCE_VALUES[item.type] ?? COMPONENT_INSURANCE_VALUE;
14	
15	const insuranceSum = (items: Item[]): number =>
16	  items.reduce((sum, item) => sum + itemInsuranceValue(item), 0);
17	
18	export interface Damage {
19	  itemType: string;
20	  amount: number;
21	}
22	
23	export interface PayoutResult {
24	  payout: number;
25	  remainingCap: number;
26	}
27	
28	const DEDUCTIBLE = 100;
29	const HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD = 8;
30	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
31	
32	const reimbursementAmount = (item: Item, damageAmount: number): number => {
33	  if ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD) {
34	    return damageAmount * HIGH_ENCHANTMENT_REIMBURSEMENT_RATE;
35	  }
36	  return damageAmount;
37	};
38	
39	const consumeMatchingItem = (availableItems: Item[], itemType: string): Item => {
40	  const index = availableItems.findIndex((item) => item.type === itemType);
41	  if (index === -1) {
42	    throw new Error(
43	      `Damage references item type "${itemType}" not covered by the policy`,
44	    );
45	  }
46	  const [item] = availableItems.splice(index, 1);
47	  return item;
48	};
49	
50	export const calculatePayout = (
51	  policyItems: Item[],
52	  damages: Damage[],
53	  capRemaining: number = insuranceSum(policyItems) * CAP_MULTIPLIER,
54	): PayoutResult => {
55	  const availableItems = [...policyItems];
56	  const payout = damages.reduce((sum, damage) => {
57	    if (damage.amount < 0) {
58	      throw new Error(`Damage amount must not be negative: ${damage.amount}`);
59	    }
60	    const item = consumeMatchingItem(availableItems, damage.itemType);
61	    return sum + reimbursementAmount(item, damage.amount) - DEDUCTIBLE;
62	  }, 0);
63	  const cappedPayout = Math.floor(Math.min(payout, capRemaining));
64	  return { payout: cappedPayout, remainingCap: capRemaining - cappedPayout };
65	};
