29	const readStdin = (): Promise<string> =>
30	  new Promise((resolve, reject) => {
31	    let data = "";
32	    process.stdin.setEncoding("utf-8");
33	    process.stdin.on("data", (chunk) => (data += chunk));
34	    process.stdin.on("end", () => resolve(data));
35	    process.stdin.on("error", reject);
36	  });
37	
38	const run = async (): Promise<void> => {
39	  const input = await readStdin();
40	  const scenario: Scenario = JSON.parse(input);
41	
42	  let quoteCount = 0;
43	  const policies = new Map<number, { items: Item[]; capRemaining?: number }>();
44	  const results: unknown[] = [];
45	
46	  scenario.steps.forEach((step, index) => {
47	    if (step.op === "quote") {
48	      const isFirstContract = quoteCount === 0;
49	      quoteCount += 1;
50	      const premium = calculatePremium(
51	        scenario.customer,
52	        step.items,
53	        isFirstContract,
54	      );
55	      policies.set(index, { items: step.items });
56	      results.push({ premium });
57	    } else {
58	      const policy = policies.get(step.policy);
59	      if (!policy) {
60	        throw new Error(`Claim references unknown policy step: ${step.policy}`);
61	      }
62	      const result = calculatePayout(
63	        policy.items,
64	        step.incident.damages,
65	        policy.capRemaining,
66	      );
67	      policy.capRemaining = result.remainingCap;
68	      results.push(result);
69	    }
70	  });
71	
72	  process.stdout.write(JSON.stringify({ results }));
73	};
74	
75	run().catch((error: Error) => {
76	  process.stderr.write(`${error.message}\n`);
77	  process.exitCode = 1;
78	});
